/* Day theme (default) */
.streak-badge {
  --streak-bg: #f5f0e6;
  --streak-fg: #2a2833;
  --streak-muted: #6b6676;
  --streak-track: #dcd3c2;
  --streak-fill: #3b7457;
  --streak-focus: #1d56b8;

  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 9rem;
  padding: 0.6rem 0.8rem;
  border-radius: 0.6rem;
  background: var(--streak-bg);
  color: var(--streak-fg);
  font-family: inherit;
  box-sizing: border-box;
}

/* Night theme: explicit attribute on the root element */
:root[data-theme="night"] .streak-badge {
  --streak-bg: #1c1d24;
  --streak-fg: #e8e6ee;
  --streak-muted: #a29eb0;
  --streak-track: #3a3b47;
  --streak-fill: #7fc8a0;
  --streak-focus: #9cb8ff;
}

/* Night theme: follow the system when no theme attribute is set */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) .streak-badge {
    --streak-bg: #1c1d24;
    --streak-fg: #e8e6ee;
    --streak-muted: #a29eb0;
    --streak-track: #3a3b47;
    --streak-fill: #7fc8a0;
    --streak-focus: #9cb8ff;
  }
}

.streak-badge__label {
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.2;
  white-space: nowrap;
}

.streak-badge__track {
  position: relative;
  width: 100%;
  height: 0.375rem;
  border-radius: 999px;
  background: var(--streak-track);
  overflow: hidden;
}

.streak-badge__fill {
  height: 100%;
  border-radius: inherit;
  background: var(--streak-fill);
  transition: width 300ms ease-out;
}

.streak-badge:focus {
  outline: none;
}

.streak-badge:focus-visible {
  outline: 2px solid var(--streak-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .streak-badge__fill {
    transition: none;
  }
}

/* Keep the progress bar visible in forced-colors (high contrast) modes */
@media (forced-colors: active) {
  .streak-badge {
    border: 1px solid CanvasText;
  }

  .streak-badge__track {
    border: 1px solid CanvasText;
    background: Canvas;
  }

  .streak-badge__fill {
    background: Highlight;
  }

  .streak-badge:focus-visible {
    outline-color: Highlight;
  }
}
